#include "../src/recycle_helper_protocol.hpp"
#include <cassert>
#include <iostream>
using namespace ww::recycle_helper;
int main(){Request r;r.port=1234;r.nonce="0123456789abcdef0123456789abcdef";r.action=Action::item;r.relative="folder/file name.txt";Request out;auto encoded=encode(r);assert(!encoded.empty()&&decode(encoded,out)&&out.relative==r.relative&&out.action==Action::item);for(const auto &path:{"../system","a/../b","/data/system","a//b","a/./b","a\\b","a/"}){r.relative=path;assert(encode(r).empty());}r.relative="";r.action=Action::empty;encoded=encode(r);assert(decode(encoded,out)&&out.action==Action::empty);assert(!decode(encoded+"garbage",out));assert(!decode("WBR2\n01234\n0123456789abcdef0123456789abcdef\nE\n\n\n-\n",out));r.action=Action::move_private;r.relative="Desktop/.winbrew-trash/123-0/file";r.expected.device=1;r.expected.inode=2;assert(decode(encode(r),out));r.relative="Desktop/../../system/.winbrew-trash/file";assert(encode(r).empty());r.action=Action::move_profile;r.relative="Desktop/.winbrew-trash/file";assert(encode(r).empty());r.action=Action::restore;r.relative="123-0/file";r.destination="Desktop/.winbrew-trash";assert(encode(r).empty());r.destination="Desktop";assert(decode(encode(r),out));std::cout<<"PASS: bin helper protocol rejects traversal, malformed requests and noncanonical encodings\n";}
